#!/usr/bin/env node
// Regenerates the vendored rhino3dm build that cad.js loads on export.
//
//   node vendor/make-rhino3dm.js <unpacked rhino3dm npm package dir>
//
// Chrome refuses fetch() of a .wasm file from file://, so the WebAssembly
// binary ships gzipped and base64-encoded inside a plain script, and cad.js
// hands the bytes to the loader as `wasmBinary`.

'use strict';

const fs = require('fs');
const path = require('path');
const zlib = require('zlib');
const crypto = require('crypto');

const src = process.argv[2];
if (!src) {
  console.error('usage: node vendor/make-rhino3dm.js <rhino3dm package dir>');
  process.exit(2);
}

const pkg = JSON.parse(fs.readFileSync(path.join(src, 'package.json'), 'utf8'));
const wasm = fs.readFileSync(path.join(src, 'rhino3dm.wasm'));
const loader = fs.readFileSync(path.join(src, 'rhino3dm.min.js'));
const sha = crypto.createHash('sha256').update(wasm).digest('hex');
const b64 = zlib.gzipSync(wasm, { level: 9 }).toString('base64');

const out = __dirname;
fs.writeFileSync(path.join(out, 'rhino3dm.min.js'), loader);
fs.writeFileSync(path.join(out, 'rhino3dm.wasm.js'), [
  '// rhino3dm ' + pkg.version + ' (MIT, Robert McNeel & Associates; see rhino3dm-LICENSE.txt).',
  '// rhino3dm.wasm, gzip then base64. Unpacked sha256: ' + sha,
  '// Generated by make-rhino3dm.js; do not edit.',
  '(function (root) {',
  "  var b64 = '" + b64 + "';",
  "  if (typeof module === 'object' && module.exports) module.exports = b64;",
  '  else root.ProgramBoardRhinoWasm = b64;',
  "})(typeof globalThis !== 'undefined' ? globalThis : this);",
  '',
].join('\n'));

console.log('rhino3dm ' + pkg.version + ': wasm ' + wasm.length + ' bytes -> payload ' + b64.length
  + ' chars; loader ' + loader.length + ' bytes');
